BEGIN TRANSACTION;
CREATE TABLE "account_headimg" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "head_img" varchar(100) NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "account_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "head_img" varchar(255) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_api_caseapi" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_api_caseapi_caseapiinfo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "caseapi_id" bigint NOT NULL REFERENCES "case_api_caseapi" ("id") DEFERRABLE INITIALLY DEFERRED, "caseapiinfo_id" bigint NOT NULL REFERENCES "case_api_caseapiinfo" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_api_caseapiinfo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "allure" text NULL CHECK ((JSON_VALID("allure") OR "allure" IS NULL)), "extract" text NULL CHECK ((JSON_VALID("extract") OR "extract" IS NULL)), "parametrize" text NULL CHECK ((JSON_VALID("parametrize") OR "parametrize" IS NULL)), "validate" text NULL CHECK ((JSON_VALID("validate") OR "validate" IS NULL)), "endpoint_id" bigint NOT NULL REFERENCES "case_api_endpoint" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_api_endpoint" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "method" varchar(8) NOT NULL, "url" varchar(255) NOT NULL, "params" text NULL CHECK ((JSON_VALID("params") OR "params" IS NULL)), "data" text NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "json" text NULL CHECK ((JSON_VALID("json") OR "json" IS NULL)), "cookies" text NULL CHECK ((JSON_VALID("cookies") OR "cookies" IS NULL)), "headers" text NULL CHECK ((JSON_VALID("headers") OR "headers" IS NULL)), "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_ui_caseui" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_ui_caseui_caseuiinfo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "caseui_id" bigint NOT NULL REFERENCES "case_ui_caseui" ("id") DEFERRABLE INITIALLY DEFERRED, "caseuiinfo_id" bigint NOT NULL REFERENCES "case_ui_caseuiinfo" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_ui_caseuiinfo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "allure" text NULL CHECK ((JSON_VALID("allure") OR "allure" IS NULL)), "step" text NULL CHECK ((JSON_VALID("step") OR "step" IS NULL)), "parametrize" text NULL CHECK ((JSON_VALID("parametrize") OR "parametrize" IS NULL)), "validate" text NULL CHECK ((JSON_VALID("validate") OR "validate" IS NULL)));
CREATE TABLE "case_ui_caseuiinfo_element" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "caseuiinfo_id" bigint NOT NULL REFERENCES "case_ui_caseuiinfo" ("id") DEFERRABLE INITIALLY DEFERRED, "element_id" bigint NOT NULL REFERENCES "case_ui_element" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "case_ui_element" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "locator" text NOT NULL CHECK ((JSON_VALID("locator") OR "locator" IS NULL)), "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_q_ormq" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(100) NOT NULL, "payload" text NOT NULL, "lock" datetime NULL);
CREATE TABLE "django_q_schedule" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "func" varchar(256) NOT NULL, "hook" varchar(256) NULL, "args" text NULL, "kwargs" text NULL, "repeats" integer NOT NULL, "next_run" datetime NULL, "task" varchar(100) NULL, "name" varchar(100) NULL, "minutes" smallint unsigned NULL CHECK ("minutes" >= 0), "cron" varchar(100) NULL, "cluster" varchar(100) NULL, "schedule_type" varchar(2) NOT NULL, "intended_date_kwarg" varchar(100) NULL);
CREATE TABLE "django_q_task" ("name" varchar(100) NOT NULL, "func" varchar(256) NOT NULL, "hook" varchar(256) NULL, "args" text NULL, "kwargs" text NULL, "result" text NULL, "started" datetime NOT NULL, "stopped" datetime NOT NULL, "success" bool NOT NULL, "id" varchar(32) NOT NULL PRIMARY KEY, "group" varchar(100) NULL, "attempt_count" integer NOT NULL, "cluster" varchar(100) NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "project_config" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "conftest" text NOT NULL, "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "project_project" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "description" varchar(128) NOT NULL, "base_url" varchar NOT NULL, "project_leader_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "project_project_user_list" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "suite_runresult" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "path" varchar(256) NOT NULL, "is_pass" bool NOT NULL, "create_datetime" datetime NOT NULL, "update_datetime" datetime NOT NULL, "suite_id" bigint NOT NULL REFERENCES "suite_suite" ("id") DEFERRABLE INITIALLY DEFERRED, "status" integer NOT NULL);
CREATE TABLE "suite_suite" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "description" varchar(32) NOT NULL, "project_id" bigint NOT NULL REFERENCES "project_project" ("id") DEFERRABLE INITIALLY DEFERRED, "cron" varchar(32) NOT NULL, "run_type" varchar NOT NULL, "schedule_id" integer NULL REFERENCES "django_q_schedule" ("id") DEFERRABLE INITIALLY DEFERRED, "hook" varchar(255) NOT NULL);
CREATE TABLE "suite_suite_case_api_list" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "suite_id" bigint NOT NULL REFERENCES "suite_suite" ("id") DEFERRABLE INITIALLY DEFERRED, "caseapi_id" bigint NOT NULL REFERENCES "case_api_caseapi" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "suite_suite_case_ui_list" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "suite_id" bigint NOT NULL REFERENCES "suite_suite" ("id") DEFERRABLE INITIALLY DEFERRED, "caseui_id" bigint NOT NULL REFERENCES "case_ui_caseui" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "system_department" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "description" varchar(128) NOT NULL, "leader_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "system_position" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL, "is_leader" bool NOT NULL);
CREATE TABLE "system_role" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "department_id" bigint NOT NULL REFERENCES "system_department" ("id") DEFERRABLE INITIALLY DEFERRED, "position_id" bigint NOT NULL REFERENCES "system_position" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
